typedef void (*callback_t)(int);
void process_event(int event_code, callback_t callback) {
    // Perform some processing
    callback(event_code); // Invoke callback with event code
}
void my_callback(int code) {
    printf("Event code: %d\n", code);
}
int main() {
    process_event(42, my_callback);
    return 0;
}
